/*
 * Example demonstrating the use of tgkill via the raw syscall(2) interface.
 * Note: SYS_gettid is used to retrieve the unique thread ID.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <signal.h>
#include <errno.h>
#include <sys/types.h>
#include <string.h>

// Helper to get the unique Thread ID
static pid_t gettid(void) {
    return syscall(SYS_gettid);
}

int main() {
    pid_t tgid = getpid();
    pid_t tid = gettid();
    int sig = SIGUSR1; 
    int ret;

    printf("Process TGID: %d, Current TID: %d\n", tgid, tid);

    // Check if the current thread is set up to handle SIGUSR1 (optional but good practice)
    signal(SIGUSR1, SIG_IGN);

    printf("Attempting to tgkill the current thread (%d) with signal %d...\n", tid, sig);

    // Call tgkill(tgid, tid, sig) via the raw syscall interface
    // SYS_tgkill is defined in <sys/syscall.h>
    ret = syscall(SYS_tgkill, tgid, tid, sig);

    if (ret == 0) {
        printf("tgkill succeeded. Signal %d sent to thread %d.\n", sig, tid);
    } else {
        fprintf(stderr, "tgkill failed [Error %d]: %s\n", errno, strerror(errno));
        return 1;
    }

    return 0;
}
